const note=sticky('## Missing-only origin run\nOne official origin per run: database lock, fresh robots, one reviewed sitemap, at most max_pages paced product pages, missing-only ingestion. A refusal, challenge or rate limit stops the origin and is persisted; nothing is published and no image is fetched.',[beginRun,finishRun],{color:4});
export default workflow('jwleria-origin-intake','Jwleria — Origin intake run')
  .add(receive)
  .to(beginRun)
  .to(planOrigin)
  .to(hasPlan
    .onTrue(knownIds.to(fetchRobots).to(readRobots).to(robotsAllow
      .onTrue(paceSitemap.to(fetchSitemap).to(selectPages).to(pagesSelected
        .onTrue(eachPage
          .onEachBatch(checkPage.to(pageAllowed
            .onTrue(pacePage.to(fetchPage).to(assessPage).to(nextBatch(eachPage)))
            .onFalse(noteSkip.to(nextBatch(eachPage)))))
          .onDone(collectResults.to(hasRecords
            .onTrue(ingest.to(afterIngest).to(finishRun))
            .onFalse(finishRun))))
        .onFalse(finishRun)))
      .onFalse(finishRun)))
    .onFalse(finishRun))
  .add(note);
